{
  "title": "寻找神秘的春牛",
  "scene": "在一个古老的村庄里，有一座只有在春分时节才会出现的神牛雕像。相传这只春牛是村庄的守护神，只有最勇敢的孩子才能找到它。今天正是春分，村里的孩子们都在猜测春牛会出现在哪里。你是一个勇敢的小男孩，决定踏上寻找春牛的冒险之旅。",
  "goal": "找到并解开春牛身上的谜题，让它出现。",
  "choices": [
    {
      "id": "A",
      "text": "去村中心的祠堂寻找线索",
      "outcome": "祠堂里的老村长告诉你，春天是万物复苏的时候，要找到春牛，可以去村后的老树林。",
      "result": "partial",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "去村头的池塘边找找看",
      "outcome": "池塘边的老人说，春牛总是隐藏在最意外的地方，你尝试了几个地方都没有发现春牛。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "C",
      "text": "询问村里的老猎人",
      "outcome": "老猎人告诉你，春牛会在太阳升起的时候出现在村后的老树林。他送你一块特殊的石片，说它可能是解开谜题的关键。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
